def _p(akt, art, tytul, tresc, lekcja, isap, slowa=""):
    return {"akt": akt, "art": art, "tytul": tytul, "tresc": tresc, "lekcja": lekcja, "isap": I[isap], "slowa": slowa}


PRZEPISY = [
    _p(KP, "art. 18", "Zasada uprzywilejowania pracownika", "Postanowienia umów o pracę i regulaminów nie mogą być mniej korzystne niż przepisy prawa pracy; mniej korzystne są nieważne, a w ich miejsce stosuje się przepisy. Korzystniejsze — są ważne.", "zrodla_prawa", "kp", "hierarchia umowa regulamin"),
    _p(KP, "art. 22 §1, §1¹, §1²", "Stosunek pracy i zakaz zastępowania go umową cywilnoprawną", "Praca określonego rodzaju na rzecz pracodawcy i pod jego kierownictwem, w miejscu i czasie przez niego wyznaczonym, za wynagrodzeniem — to stosunek pracy niezależnie od nazwy umowy. Nie wolno zastępować umowy o pracę umową cywilnoprawną przy takich warunkach.", "cudzoziemcy_b2b", "kp", "b2b zlecenie podporządkowanie"),
    _p(KP, "art. 22¹", "Dane osobowe kandydata i pracownika", "Od kandydata żądasz: imienia i nazwiska, daty urodzenia, danych kontaktowych, a gdy niezbędne — wykształcenia, kwalifikacji, przebiegu zatrudnienia. Od 24.12.2025 nie wolno żądać informacji o wynagrodzeniu w obecnym i poprzednich zatrudnieniach (pkt 6). Od pracownika dodatkowo: adres, PESEL, dane do ZUS/PIT, wykształcenie i przebieg zatrudnienia, numer konta.", "rekrutacja_jawnosc", "kp", "rodo rekrutacja"),
    _p(KP, "art. 18³ᶜᵃ (od 24.12.2025)", "Informacja o wynagrodzeniu dla kandydata", "Pracodawca przekazuje kandydatowi informację o proponowanym początkowym wynagrodzeniu lub jego przedziale (obiektywnym, neutralnym płciowo) oraz o postanowieniach układu/regulaminu — w ogłoszeniu albo przed rozmową; ogłoszenia neutralne płciowo. Brak informacji — wykroczenie z art. 281 (1 000–30 000 zł).", "rekrutacja_jawnosc", "kp", "jawność widełki"),
    _p(KP, "art. 25, 25¹", "Rodzaje umów i limit 33 miesięcy / 3 umów", "Umowa na okres próbny (do 3 mies.; 1 lub 2 mies., gdy planowana kolejna umowa jest krótsza niż 6 / 12 mies.), na czas określony, na czas nieokreślony. Łączny okres umów na czas określony — 33 miesiące, liczba — 3; przekroczenie = umowa na czas nieokreślony. Wyjątki: zastępstwo, prace dorywcze/sezonowe, kadencja, obiektywne przyczyny (zapis w umowie + PIP w 5 dni).", "umowa_o_prace", "kp", "33/3 okres próbny"),
    _p(KP, "art. 29", "Treść umowy o pracę i informacja o warunkach zatrudnienia", "Umowa określa strony, adres pracodawcy, rodzaj umowy, datę zawarcia, rodzaj i miejsce pracy, wynagrodzenie ze składnikami, wymiar czasu pracy, dzień rozpoczęcia (i dodatkowe elementy dla próbnej/określonej). Umowa na piśmie przed dopuszczeniem do pracy. W 7 dni od dopuszczenia — informacja o warunkach zatrudnienia (§3): czas pracy, przerwy, odpoczynki, nadgodziny, urlop, składniki wynagrodzenia, procedura rozwiązania, szkolenia, układ, ZUS.", "onboarding_akta", "kp", "informacja art. 29 §3"),
    _p(KP, "art. 94⁴ (rozporządzenie z 10.12.2018)", "Dokumentacja pracownicza — akta A–E, 10 lat", "Pracodawca prowadzi akta osobowe (A — rekrutacja, B — przebieg, C — ustanie, D — kary, E — kontrola trzeźwości) i dokumentację w sprawach ze stosunku pracy (ewidencja czasu pracy, urlopy, wynagrodzenia). Przechowywanie 10 lat od końca roku ustania zatrudnienia (zatrudnieni od 2019; wcześniejsi — 50 lat, chyba że ZUS OSW/RIA). Postać papierowa lub elektroniczna.", "onboarding_akta", "dok", "akta osobowe"),
    _p(KP, "art. 129, 130", "Normy czasu pracy i wymiar", "8 h na dobę i przeciętnie 40 h w przeciętnie 5-dniowym tygodniu w okresie rozliczeniowym do 4 mies. (do 12 — obiektywne przyczyny, PIP). Wymiar = tygodnie × 40 + dni pon–pt × 8 − 8 za każde święto w dniu innym niż niedziela. Rozkład na co najmniej miesiąc, przekazany tydzień wcześniej (§3).", "czas_pracy_systemy", "kp", "wymiar harmonogram"),
    _p(KP, "art. 132, 133", "Odpoczynek dobowy i tygodniowy", "11 godzin nieprzerwanego odpoczynku na dobę (wyjątki: zarządzający, akcje ratownicze — równoważny odpoczynek) i 35 godzin w tygodniu, obejmujące niedzielę (24 h przy zmianie pory w pracy zmianowej i dla zarządzających).", "czas_pracy_systemy", "kp", "odpoczynek 11 35"),
    _p(KP, "art. 135–137", "System równoważny", "Dobowy wymiar do 12 h (okres rozliczeniowy 1 mies., wyjątkowo 3–4), do 16 h przy dozorze urządzeń lub pogotowiu, do 24 h przy pilnowaniu mienia i ochronie — równoważony krótszym czasem lub dniami wolnymi; odpoczynek po 16/24 h równy liczbie przepracowanych godzin.", "czas_pracy_systemy", "kp", "równoważny 12 h"),
    _p(KP, "art. 149 (rozp. §6)", "Ewidencja czasu pracy", "Pracodawca prowadzi ewidencję dla każdego pracownika: godziny rozpoczęcia i zakończenia pracy, nadgodziny, praca w nocy, niedziele i święta, dyżury, dni wolne z tytułem, zwolnienia i nieobecności. Nie ewidencjonuje się godzin dla zadaniowego czasu pracy, kierowników komórek i ryczałtów. Ewidencja — jak akta (10 lat).", "ewidencja_czasu", "kp", "ewidencja §6"),
    _p(KP, "art. 151–151³", "Nadgodziny: limit, rekompensata, dzień wolny", "Nadgodziny tylko z konieczności (akcja ratownicza, szczególne potrzeby); limit 150 h rocznie (regulamin — więcej, do 48 h średnio tygodniowo). Dodatek 100%: noc, niedziele/święta niebędące dniami pracy, dzień wolny za nie, przekroczenie normy średniotygodniowej; 50% — pozostałe. Zamiast dodatku czas wolny 1:1 na wniosek lub 1:1,5 bez wniosku. Praca w dniu wolnym z 5-dniowego tygodnia — inny dzień wolny do końca okresu.", "nadgodziny_noc", "kp", "150 h dodatek 50 100 czas wolny"),
    _p(KP, "art. 151⁷, 151⁸", "Pora nocna i dodatek", "Pora nocna — 8 godzin między 21:00 a 7:00 (regulamin). Za każdą godzinę pracy w nocy dodatek 20% stawki godzinowej wynikającej z minimalnego wynagrodzenia (minimalne / wymiar miesiąca × 20%). Pracujący w nocy przy pracach niebezpiecznych — max 8 h na dobę.", "nadgodziny_noc", "kp", "dodatek nocny"),
    _p(KP, "art. 153–155¹, 158", "Wymiar urlopu, pierwsza praca, proporcja, uzupełniający", "20 dni (staż < 10 lat) lub 26 (≥ 10 lat); do stażu wlicza się naukę (do 8 lat) i — od 2026 — zlecenia/działalność. Pierwsza praca: 1/12 z upływem każdego miesiąca. Niepełny etat i niepełny rok — proporcjonalnie, zaokrąglenie w górę. Z chwilą uzyskania 10 lat stażu — urlop uzupełniający.", "urlop_wypoczynkowy", "kp", "20 26 dni proporcjonalny"),
    _p(KP, "art. 162, 167², 168, 171", "Udzielanie urlopu, na żądanie, zaległy, ekwiwalent", "Co najmniej jedna część urlopu — 14 kolejnych dni kalendarzowych. 4 dni na żądanie w roku (zgłoszenie najpóźniej w dniu, przed rozpoczęciem pracy). Zaległy — do 30 września następnego roku. Ekwiwalent tylko przy rozwiązaniu/wygaśnięciu umowy; od 27.01.2026 wypłata w terminie wypłaty wynagrodzenia (10 dni od ustania, gdy termin wypłaty przypada przed rozwiązaniem).", "urlop_wypoczynkowy", "kp", "na żądanie zaległy ekwiwalent"),
    _p(KP, "art. 302¹ i n. (nowelizacja 2025/2026)", "Staż pracy — zlecenia i działalność", "Do stażu pracy wlicza się okresy zleceń, umów o świadczenie usług i agencyjnych objętych ubezpieczeniem emerytalno-rentowym, działalności z opłaconymi składkami, współpracy, zasiłków z tych tytułów, pracy za granicą. Nie: dzieło, praktyki, wolontariat. Dokument: zaświadczenie ZUS (eZUS). Wejście: 1.01.2026 (publiczni), 1.05.2026 (pozostali); 24 miesiące na dokumenty.", "staz_pracy_2026", "kp", "staż zaświadczenie zus"),
    _p(KP, "art. 180, 182¹ᵃ–182¹ᶜ, 182³, 186", "Urlopy rodzicielskie", "Macierzyński 20 tyg. (14 obowiązkowe dla matki). Rodzicielski 41 tyg. (43 przy mnogim), w tym 9 tyg. nieprzenoszalnych dla każdego z rodziców, do końca roku, w którym dziecko kończy 6 lat, do 5 części; zasiłek 70% (81,5% za całość przy wniosku matki w 21 dni). Ojcowski 2 tyg. do 12. miesiąca życia dziecka. Wychowawczy do 36 mies., bezpłatny, do 6. roku życia.", "urlopy_rodzicielskie", "kp", "macierzyński rodzicielski ojcowski 41 9"),
    _p(KP, "art. 177", "Ochrona w ciąży i na urlopach", "Zakaz wypowiedzenia i rozwiązania umowy w okresie ciąży oraz urlopów macierzyńskiego/rodzicielskiego/ojcowskiego (wyjątki: upadłość/likwidacja; art. 52 za zgodą związku). Umowa na czas określony lub próbny > 1 mies., która rozwiązałaby się po 3. miesiącu ciąży — przedłuża się do porodu (nie zastępstwo).", "urlopy_rodzicielskie", "kp", "ciąża ochrona przedłużenie"),
    _p(KP, "art. 148¹, 173¹, 188, 188¹", "Siła wyższa, urlop opiekuńczy, art. 188, elastyczna organizacja", "Siła wyższa: 2 dni lub 16 h w roku, 50% wynagrodzenia, wniosek najpóźniej w dniu. Urlop opiekuńczy: 5 dni w roku, bezpłatny, na członka rodziny/domownika. Art. 188: rodzic dziecka do 14 lat — 2 dni lub 16 h, 100%. Elastyczna organizacja pracy dla rodzica dziecka do 8 lat — wniosek 21 dni, odpowiedź 7 dni.", "nieobecnosci_inne", "kp", "siła wyższa opiekuńczy 188"),
    _p(KP, "art. 85–87¹, 91", "Wypłata wynagrodzenia i potrącenia", "Wypłata co najmniej raz w miesiącu, z dołu, do 10. dnia następnego miesiąca, przelewem. Bez zgody potrącasz (po ZUS, PIT, PPK): alimenty (do 3/5), inne tytuły wykonawcze (do 1/2), zaliczki, kary (do 1/10). Kwoty wolne: 100% minimalnego netto (inne), 75% (zaliczki), 90% (kary); alimenty — bez kwoty wolnej. Inne potrącenia — tylko za pisemną zgodą (kwota wolna 100%/80%).", "potracenia", "kp", "komornik kwota wolna"),
    _p(KP, "art. 92", "Wynagrodzenie za czas choroby", "Za pierwsze 33 dni niezdolności w roku kalendarzowym (14 — pracownik po 50. roku życia) pracodawca wypłaca 80% podstawy (100% — ciąża, wypadek w drodze, dawca). Od 34./15. dnia — zasiłek chorobowy. Podstawa liczona jak zasiłek; bez składek społecznych, ze zdrowotną i PIT.", "chorobowe_podstawy", "kp", "33 dni 14 dni"),
    _p(ZAS, "art. 4, 8, 9, 11, 36–43", "Zasiłek chorobowy: wyczekiwanie, okres zasiłkowy, wysokość, podstawa", "Wyczekiwanie 30 dni (obowiązkowe) / 90 (dobrowolne). Okres zasiłkowy 182 dni (270 — ciąża, gruźlica); przerwa < 60 dni nie otwiera nowego. Zasiłek 80% (100% ciąża, wypadek w drodze, dawca; szpital 80%). Podstawa: przeciętne wynagrodzenie z 12 miesięcy po odliczeniu 13,71%, z uzupełnieniem niepełnych miesięcy; nie ustala się na nowo przy przerwie krótszej niż miesiąc kalendarzowy; minimum — minimalne wynagrodzenie po 13,71%.", "podstawa_zasilku", "zas", "182 270 podstawa 12 miesięcy uzupełnianie"),
    _p(ZAS, "art. 17, 59, 61 (nowelizacja Dz.U. 2026 poz. 26)", "Kontrola zwolnień lekarskich po 13.04.2026", "Utrata prawa do zasiłku za cały okres zwolnienia przy pracy zarobkowej (każda aktywność nastawiona na przychód, poza incydentalnymi) lub aktywności niezgodnej z celem zwolnienia (czynności życia codziennego dozwolone). Kontroluje płatnik zgłaszający > 20 ubezpieczonych (imienne upoważnienie, protokół, 3 dni na uwagi) albo ZUS; spory — decyzja ZUS. Od 1.01.2027 e-ZLA wskazuje tytuł ubezpieczenia.", "kontrola_l4_2026", "zas", "kontrola L4 praca zarobkowa"),
    _p(ZAS, "art. 32–35", "Zasiłek opiekuńczy", "80% podstawy; 60 dni w roku — zdrowe dziecko do 8 lat (zamknięcie placówki, choroba opiekuna) lub chore dziecko do 14 lat; 14 dni — inny chory członek rodziny; 30 dni — dziecko niepełnosprawne 14–18 lat; łącznie max 60 dni. Nie przysługuje, gdy inny domownik może zapewnić opiekę (poza dzieckiem do 2 lat).", "zasilki_inne", "zas", "opiekuńczy 60 14 dni"),
    _p(SYS, "art. 6, 8 ust. 2a, 9, 36", "Tytuły do ubezpieczeń, zbiegi, zgłoszenia", "Pracownik — wszystkie ubezpieczenia obowiązkowo; zleceniobiorca — emerytalne, rentowe, wypadkowe obowiązkowo, chorobowe dobrowolnie; zlecenie z własnym pracodawcą — jak etat. Zbieg: zlecenie + etat ≥ minimalnej gdzie indziej → tylko zdrowotna; kilka zleceń — sumowanie do minimalnej. Student do 26 lat na zleceniu — bez ubezpieczeń. Zgłoszenie (ZUA/ZZA) i wyrejestrowanie (ZWUA) w 7 dni.", "zus_zgloszenia", "sys", "zbieg student 7 dni ZUA"),
    _p(SYS, "art. 19, 22, 46–47", "Limit 30-krotności, stopy składek, terminy rozliczeń", "Roczna podstawa składek emerytalnej i rentowej nie wyższa niż 30 × prognozowane przeciętne wynagrodzenie (2026: 282 600 zł). Stopy: emerytalna 19,52% (po połowie), rentowa 8% (1,5 + 6,5), chorobowa 2,45%, wypadkowa 0,67–3,33% (1,67% do 9 ubezpieczonych). Deklaracje i składki: do 5. (budżet), 15. (osoby prawne), 20. (pozostali) następnego miesiąca; jeden przelew na NRS.", "zus_rozliczenia", "sys", "30-krotność terminy 15 20"),
    _p(SYS, "art. 23, 24, 41, 98", "Odsetki, przedawnienie, korekty, sankcje", "Odsetki za zwłokę jak podatkowe (nie nalicza się do 1% minimalnego wynagrodzenia). Składki przedawniają się po 5 latach — tyle też można korygować dokumenty. Korekta w 7 dni od stwierdzenia błędu (30 dni po kontroli). Wykroczenia (niezgłoszenie, nieprowadzenie dokumentacji, nieopłacanie) — grzywna do 5 000 zł; opłata dodatkowa do 100% składek.", "zus_korekty", "sys", "korekta 5 lat odsetki"),
    _p("Rozporządzenie składkowe (18.12.1998)", "§2 ust. 1", "Przychody wyłączone z podstawy składek", "Nie stanowią podstawy składek m.in.: nagrody jubileuszowe nie częściej niż co 5 lat, odprawy pieniężne i odszkodowania z tytułu rozwiązania umowy, ekwiwalenty za pranie/narzędzia/odzież, diety i zwrot kosztów podróży do limitów, ryczałt za auto prywatne do limitu, świadczenia z ZFŚS zgodne z ustawą, korzyści z układu/regulaminu polegające na zakupie po cenie niższej niż detaliczna (współfinansowane benefity).", "swiadczenia_pozaplacowe", "skl", "benefity wyłączenia ze składek"),
    _p(PIT, "art. 12, 21 ust. 1 pkt 148, 27, 31a–32, 39", "Przychód ze stosunku pracy, ulga dla młodych, skala, PIT-2, zaliczki, PIT-11", "Przychód: wszystkie wypłaty i świadczenia (także w naturze i PPK pracodawcy). Ulga dla młodych: do 26 lat, do 85 528 zł rocznie. Skala: 12% do 120 000 zł dochodu, 32% od nadwyżki; kwota zmniejszająca 300 zł/mies. na PIT-2. KUP 250/300 zł. Zaliczka do 20. następnego miesiąca; po ustaniu zatrudnienia oświadczenia pomija się. PIT-11 do końca stycznia (US) i lutego (podatnik); na wniosek po ustaniu — 14 dni.", "zaliczka_pit", "pit", "próg 120 000 PIT-2 KUP ulga dla młodych"),
    _p(PIT, "art. 21 ust. 1 pkt 11b, 26, 67, 78", "Zwolnienia: posiłki, zapomogi, ZFŚS, wypoczynek dzieci", "Zwolnione z PIT: posiłki/bony do 450 zł miesięcznie; zapomogi losowe (z ZFŚS bez limitu, inne do 6 000); świadczenia z ZFŚS pieniężne i rzeczowe do 1 000 zł rocznie (bez bonów); dofinansowanie zorganizowanego wypoczynku dzieci do 18 lat z ZFŚS bez limitu.", "swiadczenia_pozaplacowe", "pit", "ZFŚS 1 000 posiłki 450"),
    _p("Rozporządzenie o wynagrodzeniu urlopowym (8.01.1997)", "§6–§19", "Wynagrodzenie za urlop i ekwiwalent", "Stałe składniki — w wysokości z miesiąca urlopu; zmienne za okresy do miesiąca — średnia z 3 miesięcy (do 12 przy wahaniach) podzielona przez godziny przepracowane; wyłączone: nagrody jubileuszowe, ekwiwalenty, odprawy, chorobowe. Ekwiwalent: podstawa (stałe + zmienne 3 mies. + 1/12 rocznych) / współczynnik (2026: 20,92; proporcja do etatu) / norma dobowa × godziny urlopu.", "wynagrodzenie_urlopowe", "url", "współczynnik 20,92 3 miesiące"),
    _p("Rozporządzenie o minimalnym wynagrodzeniu na 2026 (11.09.2025)", "§1–2", "Minimalne wynagrodzenie 2026", "Minimalne wynagrodzenie za pracę: 4 806 zł; minimalna stawka godzinowa (zlecenia, usługi): 31,40 zł. Na 2027: 4 950 zł i 32,30 zł (rozporządzenie z 14.09.2026). Do minimalnego nie wlicza się nadgodzin, nocnego, stażowego, odprawy emerytalnej, jubileuszówki.", "wskazniki_2026", "min", "4806 31,40 4950"),
    _p("Ustawa o PPK (4.10.2018)", "art. 8, 16, 23, 25–27, 31–33", "PPK: zapis, wpłaty, rezygnacja, autozapis", "Umowa o prowadzenie po 3 miesiącach zatrudnienia (18–55 lat automatycznie, 55–70 na wniosek). Wpłaty: 2% pracownik (0,5% przy wynagrodzeniu ≤ 120% minimalnego), 1,5% pracodawca (+ dodatkowe do 2% / 2,5%), od podstawy składek emerytalno-rentowych bez limitu 30-krotności; wpłata pracodawcy to przychód do PIT bez ZUS. Rezygnacja — deklaracja; ponowny autozapis co 4 lata (1.04.2027). Powitalna 250 zł, roczna 240 zł.", "ppk", "ppk", "2% 1,5% autozapis 2027"),
    _p("Ustawa o ZFŚS (4.03.1994)", "art. 3, 5, 6, 8", "Fundusz socjalny: obowiązek, odpis, terminy, kryterium", "Obowiązkowy od 50 pracowników w przeliczeniu na etaty (20–49,99 na wniosek związków); mniejsi — fundusz lub świadczenie urlopowe (chyba że informacja do 31.01). Odpis 37,5% przeciętnego wynagrodzenia z II półrocza poprzedniego roku (2026: 2 943,23 zł), 75% do 31.05, reszta do 30.09. Świadczenia zależą od sytuacji życiowej, rodzinnej i materialnej (kryterium socjalne).", "zfss_pfron", "zfss", "odpis 2 943,23 31 maja kryterium"),
    _p("Ustawa o rehabilitacji zawodowej i społecznej (27.08.1997)", "art. 15–21, 26a", "PFRON: czas pracy niepełnosprawnych, urlop dodatkowy, wpłaty, dofinansowanie", "Umiarkowany/znaczny stopień: 7 h/35 h bez obniżenia wynagrodzenia, dodatkowa przerwa 15 min, 10 dni dodatkowego urlopu po roku, zakaz nocnej i nadgodzin (wyjątki). Pracodawca ≥ 25 etatów bez 6% niepełnosprawnych — wpłata 40,65% przeciętnego wynagrodzenia × brakujące etaty (DEK-I-0 do 20.). Dofinansowanie do wynagrodzeń (Wn-D do 25.) — kwoty wg stopnia.", "zfss_pfron", "pfron", "6% 25 etatów 7 h 35 h"),
    _p(KP, "art. 30, 32–36, 36¹, 36², 37", "Rozwiązanie umowy za wypowiedzeniem", "Tryby: porozumienie, wypowiedzenie, bez wypowiedzenia, upływ czasu. Okresy wypowiedzenia (określona i nieokreślona): 2 tyg. (< 6 mies.), 1 mies. (≥ 6 mies.), 3 mies. (≥ 3 lata); próbna: 3 dni robocze / 1 tydz. / 2 tyg. Wypowiedzenie na piśmie z przyczyną (nieokreślona i — od 2023 — określona) i pouczeniem o odwołaniu (21 dni). Skrócenie 3 mies. do 1 z odszkodowaniem; zwolnienie z obowiązku świadczenia pracy; 2–3 dni na poszukiwanie pracy.", "rozwiazanie_umowy", "kp", "okres wypowiedzenia 2 tygodnie 1 miesiąc 3 miesiące"),
    _p(KP, "art. 38, 39, 41, 52, 53, 55", "Konsultacja, ochrona, rozwiązanie bez wypowiedzenia", "Konsultacja związkowa zamiaru wypowiedzenia (5 dni na zastrzeżenia; 3 dni przy art. 52). Ochrona: 4 lata przed emeryturą (art. 39), usprawiedliwiona nieobecność (art. 41). Art. 52: ciężkie naruszenie obowiązków, przestępstwo, utrata uprawnień — w 1 miesiąc od uzyskania wiadomości. Art. 53: długotrwała choroba (3 mies. przy stażu < 6 mies.; okres zasiłkowy + 3 mies. świadczenia rehabilitacyjnego). Art. 55: rozwiązanie przez pracownika z winy pracodawcy, z odszkodowaniem.", "rozwiazanie_umowy", "kp", "art. 52 miesiąc dyscyplinarka"),
    _p("Ustawa o zwolnieniach grupowych (13.03.2003)", "art. 1–3, 8, 10", "Zwolnienia grupowe i indywidualne, odprawy", "Pracodawca ≥ 20 pracowników: grupowe, gdy w 30 dni zwalnia ≥ 10 (20–99), 10% (100–299), 30 (≥ 300) z przyczyn niedotyczących pracowników; procedura: związki/przedstawiciele, porozumienie w 20 dni lub regulamin, PUP. Odprawa 1/2/3-miesięczna (staż < 2 / 2–8 / > 8 lat), limit 15 × minimalne (72 090 zł). Zwolnienie indywidualne z wyłącznej przyczyny niedotyczącej pracownika — odprawa też przysługuje.", "odprawy_grupowe", "grup", "odprawa 72 090 grupowe"),
    _p(KP, "art. 23¹, 92¹, 93, 97, 99", "Przejście zakładu, odprawy emerytalna i pośmiertna, świadectwo pracy", "Przejście zakładu: nowy pracodawca stroną z mocy prawa, zawiadomienie 30 dni przed, pracownik może rozwiązać umowę w 2 mies. za 7-dniowym uprzedzeniem. Odprawa emerytalno-rentowa — 1-miesięczna, raz. Odprawa pośmiertna dla rodziny — 1/3/6-miesięczna (staż < 10 / ≥ 10 / ≥ 15 lat). Świadectwo pracy — w dniu ustania; sprostowanie: 14 dni pracownik, 7 dni pracodawca, 14 dni sąd; odszkodowanie za niewydanie — do 6 tygodni.", "swiadectwo_rozliczenie", "kp", "świadectwo sprostowanie przejście zakładu"),
    _p(KP, "art. 94³ (ustawa z 19.06.2026, Dz.U. 2026 poz. 1046, od 5.11.2026)", "Mobbing — nowa definicja i odszkodowanie", "Mobbing to uporczywe (powtarzalne lub długotrwałe) nękanie pracownika: poniżanie, ośmieszanie, izolowanie, zastraszanie, nieuzasadniona krytyka, utrudnianie pracy, bezpodstawne obciążanie/odbieranie zadań — bez wymogu zamiaru i bez wymogu zaniżonej oceny przydatności. Pracodawca przeciwdziała (prewencja, wykrywanie, reagowanie, wsparcie) — zasady w regulaminie/obwieszczeniu do 5.05.2027. Odszkodowanie nie niższe niż 6 × minimalne wynagrodzenie (28 836 zł), także bez rozwiązania umowy; zadośćuczynienie za rozstrój zdrowia.", "mobbing_dyskryminacja_2026", "kp", "mobbing 28 836 5.11.2026"),
    _p(KP, "art. 11³, 18³ᵃ–18³ᵉ", "Dyskryminacja i równe wynagrodzenie", "Zakaz dyskryminacji bezpośredniej i pośredniej (płeć, wiek, niepełnosprawność, rasa, religia, narodowość, przekonania, związki, pochodzenie, orientacja, rodzaj umowy, wymiar etatu — katalog otwarty), molestowania i molestowania seksualnego. Równe wynagrodzenie za jednakową pracę lub pracę jednakowej wartości. Ciężar dowodu: pracownik uprawdopodabnia, pracodawca dowodzi obiektywnych powodów. Odszkodowanie nie niższe niż minimalne wynagrodzenie.", "mobbing_dyskryminacja_2026", "kp", "dyskryminacja równe wynagrodzenie"),
    _p("Dyrektywa (UE) 2023/970 — projekt UC127 (nieuchwalony, XI 2026)", "art. 5–10 dyrektywy", "Jawność wynagrodzeń — co nadchodzi", "Prawo pracownika do informacji o średnim wynagrodzeniu w podziale na płeć dla kategorii tej samej pracy (odpowiedź w 2 mies.), zakaz klauzul poufności, przejrzyste kryteria płac i awansów, raport luki płacowej (≥ 250 co rok; 150–249 i 100–149 co 3 lata), wspólna ocena przy luce ≥ 5%, ciężar dowodu na pracodawcy. Termin transpozycji 7.06.2026 — Polska jeszcze nie wdrożyła; obowiązuje etap rekrutacyjny z 24.12.2025.", "jawnosc_wynagrodzen", "kp", "luka płacowa raport dyrektywa"),
    _p("Ustawa o ochronie sygnalistów (14.06.2024)", "art. 3, 23–25, 28", "Sygnaliści — procedura zgłoszeń wewnętrznych", "Podmiot, dla którego pracę zarobkową wykonuje ≥ 50 osób, ustala procedurę zgłoszeń wewnętrznych (konsultacje 5–10 dni; kanały pisemne i ustne; potwierdzenie przyjęcia w 7 dni; informacja zwrotna w 3 miesiące; rejestr 3 lata). Zakres: korupcja, zamówienia, finanse, bezpieczeństwo produktów, środowisko, dane, interesy UE i in. (prawo pracy — tylko gdy pracodawca rozszerzy). Zakaz działań odwetowych; odszkodowanie nie niższe niż przeciętne wynagrodzenie.", "sygnalisci_zdalna_rodo", "sygn", "sygnaliści 50 osób"),
    _p(KP, "art. 67¹⁸–67³³", "Praca zdalna", "Całkowita, hybrydowa lub okazjonalna (24 dni w roku, na wniosek). Uzgodnienie przy zawarciu umowy lub w trakcie; wniosek wiążący dla ciężarnej, rodzica dziecka do 4 lat, rodzica dziecka z niepełnosprawnością, opiekuna (odmowa tylko gdy niemożliwe, odpowiedź 7 dni). Pracodawca zapewnia narzędzia, instalację, szkolenia i pokrywa koszty energii i internetu (ryczałt/ekwiwalent — bez PIT i ZUS); BHP: ocena ryzyka, oświadczenie pracownika; kontrola w uzgodnieniu.", "sygnalisci_zdalna_rodo", "kp", "zdalna 24 dni ryczałt"),
    _p(KP, "art. 22¹ᶜ–22¹ʰ, 22², 22³", "Kontrola trzeźwości i monitoring", "Kontrola trzeźwości (i na środki odurzające): zasady w regulaminie/obwieszczeniu (grupy, metoda, częstotliwość), informacja 2 tygodnie wcześniej, urządzenie z kalibracją; niedopuszczenie przy ≥ 0,2‰; wynik w aktach E (rok). Monitoring wizyjny: cele (bezpieczeństwo, mienie, produkcja, tajemnica), nie w pomieszczeniach socjalnych/związkowych, nagrania do 3 miesięcy, regulamin + informacja 2 tygodnie przed, oznaczenie. Monitoring poczty — bez naruszania tajemnicy korespondencji.", "sygnalisci_zdalna_rodo", "kp", "monitoring 3 miesiące trzeźwość"),
    _p("Ustawa o warunkach dopuszczalności powierzania pracy cudzoziemcom (20.03.2025, od 1.06.2025)", "art. 3–10, 60–65", "Zatrudnianie cudzoziemców", "Wnioski wyłącznie elektronicznie przez praca.gov.pl; zezwolenie na pracę (wojewoda) bez testu rynku pracy; oświadczenie o powierzeniu pracy (PUP, do 24 mies.) dla obywateli Armenii, Białorusi, Gruzji, Mołdawii, Ukrainy; obywatele Ukrainy ze statusem UKR — powiadomienie PUP w 14 dni. Obowiązek umowy pisemnej z tłumaczeniem, kopii dokumentu pobytowego w aktach, zgłoszenia zmian. Kary za nielegalne powierzenie pracy 3 000–50 000 zł.", "cudzoziemcy_b2b", "cudz", "cudzoziemcy praca.gov.pl 14 dni"),
    _p("Kodeks postępowania cywilnego", "art. 881–884", "Zajęcie wynagrodzenia przez komornika", "Komornik zawiadamia pracodawcę o zajęciu; pracodawca w 7 dni przedstawia zestawienie wynagrodzenia za 3 miesiące, inne zajęcia i przeszkody, a potrącone kwoty przekazuje komornikowi (lub wierzycielowi). Zajęcie obowiązuje także przy zmianie pracodawcy (wpis w świadectwie). Za niewykonanie obowiązków — grzywna do 5 000 zł.", "potracenia", "kpc", "art. 882 komornik 7 dni"),
    _p("Ustawa o Państwowej Inspekcji Pracy (13.04.2007)", "art. 10–11, 21–37", "Kontrola PIP, środki prawne, wykroczenia (art. 281–283 KP)", "Inspektor kontroluje bez uprzedzenia na podstawie legitymacji (upoważnienie w 7 dni); ma wstęp, wgląd w dokumenty, przesłuchania. Środki: nakaz (BHP, wypłata wynagrodzenia — natychmiast wykonalny), wystąpienie (odpowiedź w 30 dni), mandat 1 000–2 000 zł (do 5 000 przy recydywie), wniosek do sądu (grzywna 1 000–30 000 zł), zawiadomienie prokuratury. Zastrzeżenia do protokołu — 7 dni.", "kontrola_pip_zus", "pip", "PIP nakaz wystąpienie mandat"),
]
